/**
 * Panther Buy Bonus pricing.
 *
 * A bought feature's bomb multiplier applies once to the whole session, so a
 * free spin is worth more in a longer session. Each title's measured curve
 * (./buy-curve.ts, generated by scripts/calibrate-panther.ts) gives the fair
 * price per spin at every quantity; superadmin's buyFeatureMult is the price at
 * the standard award (freeSpinsBase) and scales the whole curve.
 */
import { PANTHER_BUY_CURVE } from "./buy-curve";

export function pantherBuyPricePerSpin(
  gameId: string,
  buyFeatureMult: number,
  freeSpinsBase: number,
  quantity: number,
): number {
  const curve = PANTHER_BUY_CURVE[gameId];
  if (!curve?.length) return buyFeatureMult;
  const at = (q: number) => curve[Math.min(curve.length, Math.max(1, Math.round(q))) - 1]!;
  return Math.round(at(quantity) * (buyFeatureMult / at(freeSpinsBase)) * 100) / 100;
}
